#!/usr/bin/env bash
# Seeds a repo with an existing CLAUDE.md and no AGENTS.md or fast profile.
set -euo pipefail

mkdir -p src/main/java/com/acme/billing src/main/generated/com/acme/billing/api \
  src/main/openapi

cat >src/main/openapi/billing.yaml <<'YAML'
openapi: 3.0.3
info: {title: billing, version: '1'}
paths: {}
YAML

cat >src/main/generated/com/acme/billing/api/InvoiceApi.java <<'JAVA'
package com.acme.billing.api;

// Generated by openapi-generator. Do not edit.
public interface InvoiceApi {
}
JAVA

cat >pom.xml <<'XML'
<project xmlns="http://maven.apache.org/POM/4.0.0">
  <modelVersion>4.0.0</modelVersion>
  <groupId>com.acme</groupId>
  <artifactId>billing</artifactId>
  <version>1.0.0-SNAPSHOT</version>
  <properties>
    <maven.compiler.release>21</maven.compiler.release>
  </properties>
  <build>
    <plugins>
      <plugin>
        <groupId>org.openapitools</groupId>
        <artifactId>openapi-generator-maven-plugin</artifactId>
        <version>7.8.0</version>
        <executions>
          <execution>
            <goals><goal>generate</goal></goals>
            <configuration>
              <inputSpec>${project.basedir}/src/main/openapi/billing.yaml</inputSpec>
              <generatorName>java</generatorName>
              <output>${project.basedir}/src/main/generated</output>
            </configuration>
          </execution>
        </executions>
      </plugin>
    </plugins>
  </build>
</project>
XML

mkdir -p .mvn/wrapper
cat >.mvn/wrapper/maven-wrapper.properties <<'PROPS'
distributionUrl=https://repo.maven.apache.org/maven2/org/apache/maven/apache-maven/3.9.9/apache-maven-3.9.9-bin.zip
PROPS
cat >mvnw <<'SH'
#!/bin/sh
# Maven Wrapper (only-script); downloads the distributionUrl above on first use.
exec "${MAVEN_HOME:-$HOME/.m2/wrapper/dists/apache-maven-3.9.9}/bin/mvn" "$@"
SH
chmod +x mvnw

cat >CLAUDE.md <<'MD'
# billing

- Run tests with `./mvnw test`.
- `src/main/generated/` is produced by the OpenAPI generator — never edit it; regenerate with `./mvnw generate-sources`.
- Money is always `BigDecimal` with scale 2; never `double`.
MD

# Commit the fixture so CLAUDE.md is tracked (git mv applies). Isolated from
# the operator's git config (signing, hooks) — this runs as you.
g() {
  command git -c user.name=eval -c user.email=eval@example.com \
    -c commit.gpgsign=false -c core.hooksPath=/dev/null "$@"
}

g init -q -b main
g add -A
g commit -qm "initial"
